-- Test DB migration (project smofdbjgcgdmscamknpw ONLY): short_description, steam_updated_at, and safe atomic delete_mod RPC.
alter table public.mods add column if not exists short_description text not null default '';
alter table public.mods add column if not exists steam_updated_at timestamptz;
grant update (short_description, steam_updated_at) on public.mods to authenticated;
grant delete on public.mods to authenticated;
do $$ begin if not exists (select 1 from pg_catalog.pg_policies where schemaname='public' and tablename='mods' and policyname='owner mod delete') then create policy "owner mod delete" on public.mods for delete to authenticated using (owner_id=(select auth.uid()) and (select public.is_authorized_user())); end if; end $$;
create or replace function public.delete_mod(p_mod_id uuid) returns void language plpgsql security invoker set search_path='' as $$ declare v_owner uuid := (select auth.uid()); v_exists boolean; begin if v_owner is null or not (select public.is_authorized_user()) then raise exception 'PZ_DENIED' using errcode='42501'; end if; if p_mod_id is null then raise exception 'PZ_INVALID_MOD' using errcode='22023'; end if; select exists(select 1 from public.mods where id=p_mod_id and owner_id=v_owner) into v_exists; if not v_exists then raise exception 'PZ_MOD_NOT_FOUND' using errcode='P0002'; end if; if exists(select 1 from public.profile_mod_choices c join public.mod_ids mi on mi.id=c.mod_id_entry_id where mi.mod_id=p_mod_id) or exists(select 1 from public.mod_relations r join public.mod_ids mi on mi.id=r.subject_mod_id_entry_id or mi.id=r.target_mod_id_entry_id where mi.mod_id=p_mod_id) then raise exception 'PZ_MOD_IN_USE' using errcode='PZ003'; end if; delete from public.mod_category_primary where mod_id=p_mod_id and owner_id=v_owner; delete from public.mod_categories where mod_id=p_mod_id and owner_id=v_owner; delete from public.mods where id=p_mod_id and owner_id=v_owner; end $$;
revoke all on function public.delete_mod(uuid) from public, anon, authenticated;
grant execute on function public.delete_mod(uuid) to authenticated;
